import base64,hashlib,hmac,gzip,os,sys,subprocess,tempfile

_mode="auto"
_salt=bytes.fromhex("3744f6ac6a2c5dd7e6981dea6fd41a92")
_mac=bytes.fromhex("c2ee62ca4794c1e6e8b93063b3f01452175b516d73e2c1831a3bbfddc9d3253f")
_e="bzIxp8xs2qF5"

if _mode=="auto":
    _s=base64.b64decode("YXlhbQ==").decode()
    _enc_k=hashlib.sha256(b"ENC:"+_s.encode()+_salt).digest()
    _mac_k=hashlib.sha256(b"MAC:"+_s.encode()+_salt).digest()
else:
    import getpass
    _iters=200000
    _pe=""
    if _pe and os.environ.get(_pe):
        _s=os.environ[_pe]
    else:
        try:
            _s=getpass.getpass("[Cassiopeia] Passphrase: ")
        except (EOFError, KeyboardInterrupt):
            sys.stderr.write("\n[X] Dibatalkan.\n")
            sys.exit(1)

    _dk=hashlib.pbkdf2_hmac(
        "sha256",_s.encode(),_salt,_iters,dklen=64
    )
    _enc_k,_mac_k=_dk[:32],_dk[32:]

_d=base64.b64decode(os.environ.pop(_e,""))
_calc=hmac.new(_mac_k,_d,hashlib.sha256).digest()

if not hmac.compare_digest(_calc,_mac):
    sys.stderr.write("[X] Passphrase salah atau payload rusak.\n")
    sys.exit(1)

_x=bytes(b^_enc_k[i%32] for i,b in enumerate(_d))

try:
    _r=gzip.decompress(_x)
except Exception as e:
    sys.stderr.write("[X] Gagal decompress: "+str(e)+"\n")
    sys.exit(1)

_tmp_path=None
try:
    _fd,_tmp_path=tempfile.mkstemp(prefix=".obf-",suffix=".sh")
    os.fchmod(_fd,0o700)

    with os.fdopen(_fd,"wb") as _tf:
        _tf.write(_r)
        _tf.flush()
    _tty_fd=None
    try:
        _tty_fd=os.open("/dev/tty", os.O_RDWR)
    except OSError:
        _tty_fd=None

    _p=subprocess.run(
        ["bash",_tmp_path]+sys.argv[1:],
        stdin=_tty_fd if _tty_fd is not None else None
    )

    if _tty_fd is not None:
        os.close(_tty_fd)
        _tty_fd=None

except Exception as e:
    sys.stderr.write("[X] Gagal eksekusi: "+str(e)+"\n")
    sys.exit(1)

finally:
    if _tmp_path:
        try:
            os.unlink(_tmp_path)
        except OSError:
            pass

sys.exit(_p.returncode)
